<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`git init\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | Initialize new repository | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`git init my-project\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> |</span></span>
